import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 기본 크기 20, 최대 200
const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 200;
// 가정: 결정세액·기납부세액 산출 출처가 미정이므로 0으로 둔다 (개발 담당자가 정한다)
const DETERMINED_TAX_BASE = 0;
const PREPAID_TAX_BASE = 0;

function num(v: unknown): number | null {
  if (typeof v === 'number') {
    return Number.isFinite(v) ? v : null;
  }
  if (typeof v === 'string' && v.trim() !== '') {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function intOf(v: unknown): number | null {
  const n = num(v);
  return n !== null && Number.isInteger(n) ? n : null;
}

function needInt(v: unknown, status: number, code: string, message: string): number {
  const n = intOf(v);
  if (n === null) {
    throw new ApiError(status, code, message);
  }
  return n;
}

function optInt(v: unknown, status: number, code: string, message: string): number | null {
  if (isBlank(v)) {
    return null;
  }
  return needInt(v, status, code, message);
}

function optText(v: unknown, max: number, status: number, code: string, message: string): string | null {
  if (isBlank(v)) {
    return null;
  }
  if (typeof v !== 'string' || v.length > max) {
    throw new ApiError(status, code, message);
  }
  return v;
}

function needText(v: unknown, max: number, status: number, code: string, message: string): string {
  const s = optText(v, max, status, code, message);
  if (s === null || s.trim() === '') {
    throw new ApiError(status, code, message);
  }
  return s;
}

function pageOf(query: Record<string, unknown>): { page: number; size: number } {
  const page = isBlank(query['page']) ? 0 : intOf(query['page']);
  const size = isBlank(query['size']) ? DEFAULT_PAGE_SIZE : intOf(query['size']);
  if (page === null || page < 0 || size === null || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 범위 값이 올바르지 않습니다.');
  }
  return { page, size: Math.min(size, MAX_PAGE_SIZE) };
}

@Controller('api/v1')
export class FnSfr02307Controller {
  @Post('/year-end-items')
  @HttpCode(200)
  async createYearEndItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const bad = 'YEAR_END_ITEM_INVALID_INPUT';
    const settlementYear = needInt(data['settlementYear'], 422, bad, '정산 연도를 숫자로 입력해 주세요.');
    if (settlementYear <= 2000) {
      throw new ApiError(422, bad, '정산 연도는 2000보다 커야 합니다.');
    }
    const itemCode = needText(data['itemCode'], 50, 422, bad, '항목 코드를 50자 이내로 입력해 주세요.');
    const itemName = needText(data['itemName'], 200, 422, bad, '항목명을 200자 이내로 입력해 주세요.');
    const useYn = data['useYn'];
    if (useYn !== '사용' && useYn !== '미사용') {
      throw new ApiError(422, bad, '사용 여부는 사용 또는 미사용이어야 합니다.');
    }
    const sortOrder = optInt(data['sortOrder'], 422, bad, '정렬 순서는 정수여야 합니다.');
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT year_end_item_id FROM year_end_item WHERE settlement_year = CAST(:settlementYear AS integer) AND item_code = :itemCode',
        { settlementYear, itemCode },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'YEAR_END_ITEM_DUPLICATED', '같은 정산 연도에 동일한 항목 코드가 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO year_end_item (settlement_year, item_code, item_name, use_yn, sort_order, created_at, updated_at) '
          + 'VALUES (CAST(:settlementYear AS integer), :itemCode, :itemName, :useYn, CAST(:sortOrder AS integer), now(), now()) '
          + 'RETURNING year_end_item_id AS "yearEndItemId"',
        { settlementYear, itemCode, itemName, useYn, sortOrder },
      );
      return { yearEndItemId: Number(rows[0].yearEndItemId) };
    });
  }

  @Get('/year-end-items')
  async listYearEndItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const { page, size } = pageOf(query);
    const year = optInt(query['settlementYear'], 400, 'VALIDATION_FAILED', '정산 연도는 숫자여야 합니다.');
    return transaction(async (db) => {
      const where = year === null ? '' : ' WHERE settlement_year = CAST(:year AS integer)';
      const countRows = await db.query('SELECT COUNT(*) AS total FROM year_end_item' + where, { year });
      const items = await db.query(
        'SELECT year_end_item_id AS "yearEndItemId", settlement_year AS "settlementYear", item_code AS "itemCode", '
          + 'item_name AS "itemName", use_yn AS "useYn", sort_order AS "sortOrder" FROM year_end_item'
          + where
          + ' ORDER BY settlement_year DESC, sort_order, year_end_item_id LIMIT :size OFFSET :offset',
        { year, size, offset: page * size },
      );
      return { items, page, size, total: Number(countRows[0].total) };
    });
  }

  @Patch('/year-end-items/:yearEndItemId')
  async updateYearEndItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const bad = 'YEAR_END_ITEM_INVALID_INPUT';
    const id = needInt(req.params['yearEndItemId'], 404, 'YEAR_END_ITEM_NOT_FOUND', '연말정산 항목을 찾을 수 없습니다.');
    const data = checks.inputOf(req.body);
    const itemName = isBlank(data['itemName']) ? null : needText(data['itemName'], 200, 422, bad, '항목명을 200자 이내로 입력해 주세요.');
    const useYn = isBlank(data['useYn']) ? null : data['useYn'];
    if (useYn !== null && useYn !== '사용' && useYn !== '미사용') {
      throw new ApiError(422, bad, '사용 여부는 사용 또는 미사용이어야 합니다.');
    }
    const sortOrder = optInt(data['sortOrder'], 422, bad, '정렬 순서는 정수여야 합니다.');
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT year_end_item_id FROM year_end_item WHERE year_end_item_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'YEAR_END_ITEM_NOT_FOUND', '연말정산 항목을 찾을 수 없습니다.');
      }
      await db.execute(
        'UPDATE year_end_item SET item_name = COALESCE(CAST(:itemName AS varchar), item_name), '
          + 'use_yn = COALESCE(CAST(:useYn AS varchar), use_yn), '
          + 'sort_order = COALESCE(CAST(:sortOrder AS integer), sort_order), updated_at = now() '
          + 'WHERE year_end_item_id = CAST(:id AS bigint)',
        { id, itemName, useYn, sortOrder },
      );
      return { yearEndItemId: id };
    });
  }

  @Post('/year-end-data')
  @HttpCode(200)
  async createYearEndData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자', '임직원');
    const data = checks.inputOf(req.body);
    const bad = 'YEAR_END_DATA_INVALID_INPUT';
    const employeeId = needInt(data['employeeId'], 422, bad, '임직원을 선택해 주세요.');
    const yearEndItemId = needInt(data['yearEndItemId'], 422, bad, '연말정산 항목을 선택해 주세요.');
    const settlementYear = needInt(data['settlementYear'], 422, bad, '귀속 연도를 숫자로 입력해 주세요.');
    let deductionAmount: number | null = null;
    if (!isBlank(data['deductionAmount'])) {
      deductionAmount = num(data['deductionAmount']);
      if (deductionAmount === null || deductionAmount < 0) {
        throw new ApiError(422, bad, '공제 금액은 0 이상의 숫자여야 합니다.');
      }
    }
    // 가정: 부양가족 정보는 이미 암호화된 문자열로 받아 그대로 저장한다
    const dependentInfoEnc = isBlank(data['dependentInfoEnc']) ? null : data['dependentInfoEnc'];
    if (dependentInfoEnc !== null && typeof dependentInfoEnc !== 'string') {
      throw new ApiError(422, bad, '부양가족 정보 형식이 올바르지 않습니다.');
    }
    const attachmentId = optInt(data['attachmentId'], 422, bad, '증빙 첨부파일 값이 올바르지 않습니다.');
    return transaction(async (db) => {
      const item = await db.query(
        'SELECT settlement_year AS "settlementYear" FROM year_end_item WHERE year_end_item_id = CAST(:yearEndItemId AS bigint)',
        { yearEndItemId },
      );
      if (item.length === 0) {
        throw new ApiError(404, 'YEAR_END_ITEM_NOT_FOUND', '연말정산 항목을 찾을 수 없습니다.');
      }
      if (Number(item[0].settlementYear) !== settlementYear) {
        throw new ApiError(422, bad, '귀속 연도가 항목의 정산 연도와 다릅니다.');
      }
      const emp = await db.query('SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)', { employeeId });
      if (emp.length === 0) {
        throw new ApiError(422, bad, '임직원을 찾을 수 없습니다.');
      }
      if (attachmentId !== null) {
        const att = await db.query('SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)', { attachmentId });
        if (att.length === 0) {
          throw new ApiError(422, bad, '증빙 첨부파일을 찾을 수 없습니다.');
        }
      }
      const closed = await db.query(
        'SELECT year_end_data_id FROM year_end_data WHERE employee_id = CAST(:employeeId AS bigint) '
          + 'AND settlement_year = CAST(:settlementYear AS integer) AND closed_yn = true',
        { employeeId, settlementYear },
      );
      if (closed.length > 0) {
        throw new ApiError(409, 'YEAR_END_DATA_CLOSED', '마감된 자료입니다.');
      }
      const params = { employeeId, yearEndItemId, settlementYear, deductionAmount, dependentInfoEnc, attachmentId };
      const existing = await db.query(
        'SELECT year_end_data_id AS "yearEndDataId" FROM year_end_data '
          + 'WHERE employee_id = CAST(:employeeId AS bigint) AND year_end_item_id = CAST(:yearEndItemId AS bigint)',
        params,
      );
      if (existing.length > 0) {
        // 같은 임직원·항목의 자료가 이미 있으면(마감 전) 그 자료를 갱신한다
        const upd = await db.query(
          'UPDATE year_end_data SET deduction_amount = COALESCE(CAST(:deductionAmount AS numeric), deduction_amount), '
            + 'dependent_info_enc = COALESCE(:dependentInfoEnc, dependent_info_enc), '
            + 'attachment_id = COALESCE(CAST(:attachmentId AS bigint), attachment_id), updated_at = now() '
            + 'WHERE year_end_data_id = CAST(:id AS bigint) '
            + 'RETURNING year_end_data_id AS "yearEndDataId", closed_yn AS "closedYn"',
          { ...params, id: Number(existing[0].yearEndDataId) },
        );
        return { yearEndDataId: Number(upd[0].yearEndDataId), closedYn: upd[0].closedYn === true };
      }
      const rows = await db.query(
        'INSERT INTO year_end_data (employee_id, year_end_item_id, attachment_id, settlement_year, deduction_amount, '
          + 'dependent_info_enc, closed_yn, created_at, updated_at) '
          + 'VALUES (CAST(:employeeId AS bigint), CAST(:yearEndItemId AS bigint), CAST(:attachmentId AS bigint), '
          + 'CAST(:settlementYear AS integer), CAST(:deductionAmount AS numeric), :dependentInfoEnc, false, now(), now()) '
          + 'RETURNING year_end_data_id AS "yearEndDataId", closed_yn AS "closedYn"',
        params,
      );
      return { yearEndDataId: Number(rows[0].yearEndDataId), closedYn: rows[0].closedYn === true };
    });
  }

  @Patch('/year-end-data/:yearEndDataId')
  async updateYearEndData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자', '임직원');
    const bad = 'YEAR_END_DATA_INVALID_INPUT';
    const id = needInt(req.params['yearEndDataId'], 404, 'YEAR_END_DATA_NOT_FOUND', '연말정산 자료를 찾을 수 없습니다.');
    const data = checks.inputOf(req.body);
    let deductionAmount: number | null = null;
    if (!isBlank(data['deductionAmount'])) {
      deductionAmount = num(data['deductionAmount']);
      if (deductionAmount === null || deductionAmount < 0) {
        throw new ApiError(422, bad, '공제 금액은 0 이상의 숫자여야 합니다.');
      }
    }
    const dependentInfoEnc = isBlank(data['dependentInfoEnc']) ? null : data['dependentInfoEnc'];
    if (dependentInfoEnc !== null && typeof dependentInfoEnc !== 'string') {
      throw new ApiError(422, bad, '부양가족 정보 형식이 올바르지 않습니다.');
    }
    const attachmentId = optInt(data['attachmentId'], 422, bad, '증빙 첨부파일 값이 올바르지 않습니다.');
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT closed_yn AS "closedYn" FROM year_end_data WHERE year_end_data_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '연말정산 자료를 찾을 수 없습니다.');
      }
      if (found[0].closedYn === true) {
        throw new ApiError(409, 'YEAR_END_DATA_CLOSED', '마감된 자료는 수정할 수 없습니다.');
      }
      if (attachmentId !== null) {
        const att = await db.query('SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)', { attachmentId });
        if (att.length === 0) {
          throw new ApiError(422, bad, '증빙 첨부파일을 찾을 수 없습니다.');
        }
      }
      await db.execute(
        'UPDATE year_end_data SET deduction_amount = COALESCE(CAST(:deductionAmount AS numeric), deduction_amount), '
          + 'dependent_info_enc = COALESCE(:dependentInfoEnc, dependent_info_enc), '
          + 'attachment_id = COALESCE(CAST(:attachmentId AS bigint), attachment_id), updated_at = now() '
          + 'WHERE year_end_data_id = CAST(:id AS bigint)',
        { id, deductionAmount, dependentInfoEnc, attachmentId },
      );
      return { yearEndDataId: id };
    });
  }

  @Get('/year-end-data')
  async listYearEndData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const { page, size } = pageOf(query);
    const year = optInt(query['settlementYear'], 400, 'VALIDATION_FAILED', '귀속 연도는 숫자여야 합니다.');
    const employeeId = optInt(query['employeeId'], 400, 'VALIDATION_FAILED', '임직원 값이 올바르지 않습니다.');
    return transaction(async (db) => {
      const conds: string[] = [];
      const params: Record<string, unknown> = {};
      if (year !== null) {
        conds.push('settlement_year = CAST(:year AS integer)');
        params['year'] = year;
      }
      if (employeeId !== null) {
        conds.push('employee_id = CAST(:employeeId AS bigint)');
        params['employeeId'] = employeeId;
      }
      const where = conds.length > 0 ? ' WHERE ' + conds.join(' AND ') : '';
      const countRows = await db.query('SELECT COUNT(*) AS total FROM year_end_data' + where, params);
      const rows = await db.query(
        'SELECT year_end_data_id AS "yearEndDataId", employee_id AS "employeeId", year_end_item_id AS "yearEndItemId", '
          + 'settlement_year AS "settlementYear", deduction_amount AS "deductionAmount", closed_yn AS "closedYn" '
          + 'FROM year_end_data'
          + where
          + ' ORDER BY settlement_year DESC, employee_id, year_end_data_id LIMIT :size OFFSET :offset',
        { ...params, size, offset: page * size },
      );
      const items = rows.map((r: Record<string, unknown>) => {
        const determinedTax = DETERMINED_TAX_BASE;
        const prepaidTax = PREPAID_TAX_BASE;
        return {
          ...r,
          deductionAmount: r['deductionAmount'] === null ? null : Number(r['deductionAmount']),
          determinedTax,
          prepaidTax,
          settlementTax: determinedTax - prepaidTax,
        };
      });
      return { items, page, size, total: Number(countRows[0].total) };
    });
  }

  @Post('/year-end-data/close')
  @HttpCode(200)
  async closeYearEndData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const bad = 'VALIDATION_FAILED';
    const employeeId = needInt(data['employeeId'], 400, bad, '임직원을 선택해 주세요.');
    const settlementYear = needInt(data['settlementYear'], 400, bad, '귀속 연도를 숫자로 입력해 주세요.');
    return transaction(async (db) => {
      const params = { employeeId, settlementYear };
      const rows = await db.query(
        'SELECT closed_yn AS "closedYn" FROM year_end_data '
          + 'WHERE employee_id = CAST(:employeeId AS bigint) AND settlement_year = CAST(:settlementYear AS integer)',
        params,
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '마감할 자료가 없습니다.');
      }
      if (rows.every((r: Record<string, unknown>) => r['closedYn'] === true)) {
        throw new ApiError(409, 'YEAR_END_DATA_CLOSED', '이미 마감되었습니다.');
      }
      // 가정: 마감 일시는 현재 시각, 마감 건수는 이번에 마감 처리한 행 수
      const closedCount = await db.execute(
        'UPDATE year_end_data SET closed_yn = true, closed_at = now(), updated_at = now() '
          + 'WHERE employee_id = CAST(:employeeId AS bigint) AND settlement_year = CAST(:settlementYear AS integer) AND closed_yn = false',
        params,
      );
      return { closedCount: Number(closedCount) };
    });
  }
}

