import { useState } from 'react';
import {
  call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles, Form, Field,
  TextInput, NumberInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Panel =
  | { kind: 'itemNew' }
  | { kind: 'itemEdit'; row: Row }
  | { kind: 'dataNew' }
  | { kind: 'dataEdit'; row: Row }
  | { kind: 'dataView'; row: Row }
  | { kind: 'close' }
  | null;

const PAGE_SIZE = 10;
const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function clean(obj: Row): Row {
  const out: Row = {};
  Object.keys(obj).forEach((k) => {
    if (!isBlank(obj[k])) {
      out[k] = obj[k];
    }
  });
  return out;
}

export default function FnSfr02307Page({ role, notify }: PageProps) {
  const [year, setYear] = useState<unknown>('');
  const [employeeId, setEmployeeId] = useState<unknown>('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [panel, setPanel] = useState<Panel>(null);
  const isPayroll = role === '급여 담당자';

  const data = useData<Page>(
    () => call<Page>('GET', '/year-end-data', role, undefined, { ...applied, page: pageNo, size: PAGE_SIZE }),
    [role, applied, pageNo],
  );
  const items = useData<Page>(
    () => call<Page>('GET', '/year-end-items', role, undefined, { settlementYear: applied['settlementYear'], page: 0, size: 200 }),
    [role, applied],
  );

  function search() {
    setPageNo(0);
    setApplied({ settlementYear: year, employeeId });
  }

  function reset() {
    setYear('');
    setEmployeeId('');
    setPageNo(0);
    setApplied({});
  }

  function done(message: string) {
    notify(message);
    setPanel(null);
    data.reload();
    items.reload();
  }

  const rows = data.data ? data.data.items : [];
  const itemRows = items.data ? items.data.items : [];
  const closedOnPage = rows.filter((r) => r['closedYn'] === true).length;
  const settlementSum = rows.reduce((sum, r) => sum + Number(r['settlementTax'] || 0), 0);

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>현황</h2>
        <Tiles
          items={[
            ['자료 건수', <Num value={data.data ? data.data.total : 0} />],
            ['항목 수', <Num value={items.data ? items.data.total : 0} />],
            ['마감 건수(현재 쪽)', <Num value={closedOnPage} />],
            ['차감징수(환급)세액 합계(현재 쪽)', <Num value={settlementSum} />],
          ]}
        />
      </section>

      <section className='box span-8'>
        <h2>연말정산 자료</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='귀속 연도'>
            <NumberInput value={year} onChange={setYear} />
          </Field>
          <Field label='임직원'>
            <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        <Band total={data.data ? data.data.total : 0}>
          <button type='button' onClick={() => setPanel({ kind: 'dataNew' })}>공제 자료 입력</button>
          {isPayroll && <button type='button' onClick={() => setPanel({ kind: 'close' })}>자료 확정(마감)</button>}
        </Band>
        {data.error && <ErrorText text={data.error} />}
        <DataTable
          rows={rows}
          empty='조회된 자료가 없습니다.'
          onRowClick={(row) => setPanel({ kind: 'dataView', row })}
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table='employee' role={role} value={r['employeeId']} /> },
            { key: 'yearEndItemId', label: '연말정산 항목', render: (r) => <RefName table='year_end_item' role={role} value={r['yearEndItemId']} /> },
            { key: 'settlementYear', label: '귀속 연도' },
            { key: 'deductionAmount', label: '공제 금액', render: (r) => <Num value={r['deductionAmount']} /> },
            { key: 'settlementTax', label: '차감징수(환급)세액', render: (r) => <Num value={r['settlementTax']} /> },
            { key: 'closedYn', label: '마감 여부', render: (r) => <Badge value={r['closedYn'] === true ? '마감' : '진행'} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => (r['closedYn'] === true ? null : (
                <button
                  type='button'
                  onClick={(e) => {
                    e.stopPropagation();
                    setPanel({ kind: 'dataEdit', row: r });
                  }}
                >
                  수정
                </button>
              )),
            },
          ]}
        />
        <Pager page={pageNo} size={PAGE_SIZE} total={data.data ? data.data.total : 0} onPage={setPageNo} />
      </section>

      <section className='box span-4'>
        <h2>정산 항목</h2>
        <Band total={items.data ? items.data.total : 0}>
          {isPayroll && <button type='button' onClick={() => setPanel({ kind: 'itemNew' })}>항목 등록</button>}
        </Band>
        {items.error && <ErrorText text={items.error} />}
        <DataTable
          rows={itemRows}
          empty='등록된 항목이 없습니다.'
          columns={[
            { key: 'settlementYear', label: '정산 연도' },
            { key: 'itemName', label: '항목명' },
            { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r['useYn']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => (isPayroll ? (
                <button type='button' onClick={() => setPanel({ kind: 'itemEdit', row: r })}>수정</button>
              ) : null),
            },
          ]}
        />
      </section>

      {panel && panel.kind === 'itemNew' && (
        <Drawer title='연말정산 항목 등록' onClose={() => setPanel(null)}>
          <ItemForm role={role} onDone={done} />
        </Drawer>
      )}
      {panel && panel.kind === 'itemEdit' && (
        <Drawer title='연말정산 항목 수정' onClose={() => setPanel(null)}>
          <ItemForm role={role} row={panel.row} onDone={done} />
        </Drawer>
      )}
      {panel && panel.kind === 'dataNew' && (
        <Drawer title='공제 자료 입력' onClose={() => setPanel(null)}>
          <DataForm role={role} onDone={done} />
        </Drawer>
      )}
      {panel && panel.kind === 'dataEdit' && (
        <Drawer title='공제 자료 수정' onClose={() => setPanel(null)}>
          <DataForm role={role} row={panel.row} onDone={done} />
        </Drawer>
      )}
      {panel && panel.kind === 'dataView' && (
        <Drawer title='연말정산 결과' onClose={() => setPanel(null)}>
          <Pairs
            items={[
              ['임직원', <RefName table='employee' role={role} value={panel.row['employeeId']} />],
              ['연말정산 항목', <RefName table='year_end_item' role={role} value={panel.row['yearEndItemId']} />],
              ['귀속 연도', String(panel.row['settlementYear'])],
              ['공제 금액', <Num value={panel.row['deductionAmount']} />],
              ['결정세액', <Num value={panel.row['determinedTax']} />],
              ['기납부세액', <Num value={panel.row['prepaidTax']} />],
              ['차감징수(환급)세액', <Num value={panel.row['settlementTax']} />],
              ['마감 여부', <Badge value={panel.row['closedYn'] === true ? '마감' : '진행'} />],
            ]}
          />
        </Drawer>
      )}
      {panel && panel.kind === 'close' && (
        <Drawer title='자료 확정(마감)' onClose={() => setPanel(null)}>
          <CloseForm role={role} onDone={done} />
        </Drawer>
      )}
    </div>
  );
}

function ItemForm({ role, row, onDone }: { role: string; row?: Row; onDone: (message: string) => void }) {
  const editing = row !== undefined;
  const [settlementYear, setSettlementYear] = useState<unknown>(row ? row['settlementYear'] : '');
  const [itemCode, setItemCode] = useState<unknown>(row ? row['itemCode'] : '');
  const [itemName, setItemName] = useState<unknown>(row ? row['itemName'] : '');
  const [useYn, setUseYn] = useState<unknown>(row ? row['useYn'] : '사용');
  const [sortOrder, setSortOrder] = useState<unknown>(row ? row['sortOrder'] : '');

  async function submit() {
    if (editing) {
      await call('PATCH', '/year-end-items/' + String(row['yearEndItemId']), role, clean({ itemName, useYn, sortOrder }));
      onDone('연말정산 항목을 수정했습니다.');
      return;
    }
    if (isBlank(settlementYear) || isBlank(itemCode) || isBlank(itemName) || isBlank(useYn)) {
      throw new Error('정산 연도, 항목 코드, 항목명, 사용 여부를 모두 입력해 주세요.');
    }
    await call('POST', '/year-end-items', role, clean({ settlementYear, itemCode, itemName, useYn, sortOrder }));
    onDone('연말정산 항목을 등록했습니다.');
  }

  return (
    <Form onSubmit={submit} submit={editing ? '수정' : '등록'}>
      {!editing && (
        <Field label='정산 연도' required>
          <NumberInput value={settlementYear} onChange={setSettlementYear} />
        </Field>
      )}
      {!editing && (
        <Field label='항목 코드' required>
          <TextInput value={itemCode} onChange={setItemCode} />
        </Field>
      )}
      <Field label='항목명' required>
        <TextInput value={itemName} onChange={setItemName} />
      </Field>
      <Field label='사용 여부' required>
        <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} />
      </Field>
      <Field label='정렬 순서'>
        <NumberInput value={sortOrder} onChange={setSortOrder} />
      </Field>
    </Form>
  );
}

function DataForm({ role, row, onDone }: { role: string; row?: Row; onDone: (message: string) => void }) {
  const editing = row !== undefined;
  const [employeeId, setEmployeeId] = useState<unknown>('');
  const [yearEndItemId, setYearEndItemId] = useState<unknown>('');
  const [settlementYear, setSettlementYear] = useState<unknown>('');
  const [deductionAmount, setDeductionAmount] = useState<unknown>(row ? row['deductionAmount'] : '');
  const [dependentInfoEnc, setDependentInfoEnc] = useState<unknown>('');
  const [attachmentId, setAttachmentId] = useState<unknown>('');

  async function submit() {
    if (editing) {
      await call('PATCH', '/year-end-data/' + String(row['yearEndDataId']), role, clean({ deductionAmount, dependentInfoEnc, attachmentId }));
      onDone('공제 자료를 수정했습니다.');
      return;
    }
    if (isBlank(employeeId) || isBlank(yearEndItemId) || isBlank(settlementYear)) {
      throw new Error('임직원, 연말정산 항목, 귀속 연도를 모두 입력해 주세요.');
    }
    await call('POST', '/year-end-data', role, clean({ employeeId, yearEndItemId, settlementYear, deductionAmount, dependentInfoEnc, attachmentId }));
    onDone('공제 자료를 입력했습니다.');
  }

  return (
    <Form onSubmit={submit} submit={editing ? '수정' : '입력'}>
      {!editing && (
        <Field label='임직원' required>
          <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} />
        </Field>
      )}
      {!editing && (
        <Field label='연말정산 항목' required>
          <LookupSelect table='year_end_item' role={role} value={yearEndItemId} onChange={setYearEndItemId} />
        </Field>
      )}
      {!editing && (
        <Field label='귀속 연도' required>
          <NumberInput value={settlementYear} onChange={setSettlementYear} />
        </Field>
      )}
      <Field label='공제 금액'>
        <NumberInput value={deductionAmount} onChange={setDeductionAmount} />
      </Field>
      <Field label='부양가족 정보(암호화)' wide>
        <TextInput value={dependentInfoEnc} onChange={setDependentInfoEnc} multiline />
      </Field>
      <Field label='증빙 첨부파일'>
        <LookupSelect table='attachment' role={role} value={attachmentId} onChange={setAttachmentId} />
      </Field>
    </Form>
  );
}

function CloseForm({ role, onDone }: { role: string; onDone: (message: string) => void }) {
  const [employeeId, setEmployeeId] = useState<unknown>('');
  const [settlementYear, setSettlementYear] = useState<unknown>('');

  async function submit() {
    if (isBlank(employeeId) || isBlank(settlementYear)) {
      throw new Error('임직원과 귀속 연도를 입력해 주세요.');
    }
    const result = await call('POST', '/year-end-data/close', role, { employeeId, settlementYear });
    onDone('연말정산 자료 ' + String(result['closedCount']) + '건을 마감했습니다.');
  }

  return (
    <Form onSubmit={submit} submit='확정(마감)' danger note='마감된 자료는 수정할 수 없습니다.'>
      <Field label='임직원' required>
        <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} />
      </Field>
      <Field label='귀속 연도' required>
        <NumberInput value={settlementYear} onChange={setSettlementYear} />
      </Field>
    </Form>
  );
}
